// SPDX-License-Identifier: BSD-3-Clause
// Public TypeScript surface for the whiteout-node package.
//
// Mirrors whiteout-wasm/index.d.ts so portable code can swap import paths
// without changing API. Adds the Node-only OsFileSystem / SimpleThreadPool
// / HttpHandler surface on top.
//
// Format-specific types are autogenerated under ./types/. This file is
// hand-written and bolts the WhiteoutNodeAPI interface (the return value
// of the Whiteout() entrypoint) on top of those.

import type * as mdx from "./types/mdx";
import type * as m2  from "./types/m2";
import type * as m3  from "./types/m3";
import type * as textures from "./types/textures";

import type {
    EmbindObject, EmbindVector, EnumValue,
    Vector2f, Vector3f, Vector4f, Quaternion,
    OsFileSystem, SimpleThreadPool, HttpHandler, HttpHandlerImpl, HttpResponse,
} from "./types/_shared";

import type { Texture } from "./types/textures";

export {
    // Generated namespaces — re-exported for type-only consumers.
    mdx, m2, m3, textures,
    // Shared building blocks.
    EmbindObject, EmbindVector, EnumValue,
    Vector2f, Vector3f, Vector4f, Quaternion, Texture,
    // Node-only.
    OsFileSystem, SimpleThreadPool, HttpHandler, HttpHandlerImpl, HttpResponse,
};


// ── Texture format facade (one per file format; identical to web) ────────

export interface TextureFormat<P extends EmbindObject, W extends EmbindObject,
                               PMode extends EnumValue, WMode extends EnumValue> {
    Parser: new (mode?: PMode) => P;
    Writer: new () => W;
    ParseMode: Record<string, PMode>;
    WriteMode: Record<string, WMode>;
    parse(bytes: Uint8Array, mode?: PMode): Texture;
    write(texture: Texture): Uint8Array;
}

export type BlpFormat  = TextureFormat<textures.BlpParser,  textures.BlpWriter,
                                       EnumValue, EnumValue>;
export type DdsFormat  = TextureFormat<textures.DdsParser,  textures.DdsWriter,
                                       EnumValue, EnumValue>;
export type PngFormat  = TextureFormat<textures.PngParser,  textures.PngWriter,
                                       EnumValue, EnumValue>;
export type JpegFormat = TextureFormat<textures.JpegParser, textures.JpegWriter,
                                       EnumValue, EnumValue>;
export type BmpFormat  = TextureFormat<textures.BmpParser,  textures.BmpWriter,
                                       EnumValue, EnumValue>;
export type TgaFormat  = TextureFormat<textures.TgaParser,  textures.TgaWriter,
                                       EnumValue, EnumValue>;


// ── Texture pipeline namespace ───────────────────────────────────────────

/** Optional second argument to `texture.generateMipmaps`. */
export interface MipmapOptions {
    /** Force a specific output mip count. Defaults to preserving the
     *  existing chain length (`Texture::kKeepMipCount`). */
    newMipCount?: number;
    /** Multi-threaded mipmap / BC7 pool. When provided, the pool-aware
     *  C++ overload runs; otherwise the calling thread does the work. */
    pool?: SimpleThreadPool | null;
}

export interface TextureNamespace {
    Texture: new () => Texture;
    PixelFormat: typeof textures.PixelFormat;
    TextureType: typeof textures.TextureType;

    create2D(format: EnumValue, width: number, height: number,
             mipCount?: number): Texture;
    create3D(format: EnumValue, width: number, height: number,
             depth: number, mipCount?: number): Texture;
    createCube(format: EnumValue, size: number, mipCount?: number): Texture;
    create2DArray(format: EnumValue, width: number, height: number,
                  arraySize: number, mipCount?: number): Texture;
    createCubeArray(format: EnumValue, size: number, arraySize: number,
                    mipCount?: number): Texture;

    /** Generate the full mip chain in place. Throws on failure. */
    generateMipmaps(tex: Texture, opts?: MipmapOptions): void;
    /** Drop leading mip levels (default 1) in place. Throws on failure. */
    downscale(tex: Texture, levels?: number): void;
    mergeChannels(sources: EmbindObject, channels: EmbindObject): Texture | null;
}


// ── Per-format model namespaces (types + parse/write helpers) ────────────

export interface MdxNamespace extends Omit<typeof mdx, never> {
    /** Parse binary MDX bytes. */
    parse(bytes: Uint8Array, upgrade?: EnumValue): mdx.Model;
    /** Parse text MDL bytes (UTF-8). */
    parseMdl(bytes: Uint8Array, upgrade?: EnumValue): mdx.Model;
    /** Encode a Model as binary MDX. */
    write(model: mdx.Model): Uint8Array;
    /** Encode a Model as text MDL. `dialect` selects the MDL text dialect:
     *  `mdx.MdlFormat.WarcraftIII` (default, engine-faithful) or
     *  `mdx.MdlFormat.Hiveworkshop` (community-tool dialect). */
    writeMdl(model: mdx.Model, dialect?: EnumValue): Uint8Array;
}

/** M2 in the Node build reads from disk via OsFileSystem — `rootPath` is
 *  the directory containing the .m2; `mainPath` is the .m2 file relative
 *  to that root. Sibling .skin/.skel/.anim/.bone files are pulled lazily. */
export interface M2Namespace extends Omit<typeof m2, never> {
    parse(rootPath: string, mainPath: string, mode?: EnumValue): m2.Model;
    parseFromDisk(rootPath: string, mainPath: string, mode?: EnumValue): m2.Model;
}

export interface M3Namespace extends Omit<typeof m3, never> {
    parse(bytes: Uint8Array, mode?: EnumValue): m3.Model;
    write(model: m3.Model): Uint8Array;
}


// ── MPQ / CASC namespaces ────────────────────────────────────────────────

export interface MpqStorage extends EmbindObject {
    readFile(name: string): Uint8Array | null;
    writeFile(name: string, data: Uint8Array, opts?: any): boolean;
    fileExists(name: string): boolean;
    close(): void;
    save(): boolean;
}

export interface MpqNamespace {
    Storage: any;
    FormatVersion: Record<string, EnumValue>;
    Compression: Record<string, EnumValue>;
    /** Open a .mpq from disk, optionally with a parallel decompression pool. */
    open(path: string, pool?: SimpleThreadPool | null): MpqStorage | null;
    /** Persist an in-memory `Storage::create()` archive to disk. */
    saveTo(storage: MpqStorage, path: string): boolean;
    [k: string]: any;
}

export interface CascStorage extends EmbindObject {
    readFile(path: string): Uint8Array | null;
    readFileById(fileId: number): Uint8Array | null;
    fileExists(path: string): boolean;
    fileExistsById(fileId: number): boolean;
    close(): void;
}

export interface CascNamespace {
    Storage: any;
    /** Open a local CASC install (e.g. a WoW Data directory). */
    open(path: string, pool?: SimpleThreadPool | null): CascStorage | null;
}


// ── Top-level API ────────────────────────────────────────────────────────

export interface WhiteoutNodeAPI {
    /** Combine Embind enum values (or raw integers) into a u32 bitmask. */
    flags(...values: Array<number | EnumValue>): number;

    /** Raw Embind module — escape hatch for anything not surfaced. */
    module: any;

    // ── Shared types (constructors / value classes / enums) ──────────────
    Texture:     new () => Texture;
    PixelFormat: typeof textures.PixelFormat;
    TextureType: typeof textures.TextureType;
    Vector2f:    new () => Vector2f;
    Vector3f:    new () => Vector3f;
    Vector4f:    new () => Vector4f;
    Quaternion:  new () => Quaternion;

    // ── Node additions ──────────────────────────────────────────────────
    OsFileSystem:     new (rootPath: string) => OsFileSystem;
    SimpleThreadPool: new (nThreads: number) => SimpleThreadPool;

    /** Spawn a SimpleThreadPool. The hosting WASM binary was linked with
     *  a fixed pre-spawned worker_thread count (`-sPTHREAD_POOL_SIZE`); asking
     *  for more is legal but blocks until additional pthreads are created. */
    threadPool(n: number): SimpleThreadPool;

    /** Wrap a JS object as an HttpHandler the C++ side can call. */
    makeHttpHandler(impl: HttpHandlerImpl): HttpHandler;

    /** Math-type factories — sugar for the value_object literal pattern. */
    vec2(x: number, y: number): Vector2f;
    vec3(x: number, y: number, z: number): Vector3f;
    vec4(x: number, y: number, z: number, w: number): Vector4f;
    quat(x: number, y: number, z: number, w: number): Quaternion;

    /** Texture pipeline helpers — factory wrappers + mip ops (pool-aware). */
    texture: TextureNamespace;

    // ── Per-format facades ───────────────────────────────────────────────
    blp:  BlpFormat;
    dds:  DdsFormat;
    png:  PngFormat;
    jpeg: JpegFormat;
    bmp:  BmpFormat;
    tga:  TgaFormat;

    mdx: MdxNamespace;
    m2:  M2Namespace;
    m3:  M3Namespace;
    wem: { parse(bytes: Uint8Array, mode?: EnumValue): EmbindObject;
           write(model: EmbindObject): Uint8Array; }
         & { [k: string]: any };

    mpq: MpqNamespace;

    /** `null` when the WASM was built without CASC support. */
    casc: CascNamespace | null;
}

/** Asynchronously instantiate the Node-flavoured WASM module. */
export function Whiteout(): Promise<WhiteoutNodeAPI>;
export default Whiteout;
